#include "offline_dictionary.h"
#include "underlay.h"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <cstdio>
#include <source_location>
#include <QRegularExpression>
namespace {unsigned checks{};void verify(bool ok,std::source_location at=std::source_location::current()){++checks;if(!ok)throw std::runtime_error("Dictionary chain regression line "+std::to_string(at.line()));}}
int main(int argc,char**argv){QCoreApplication app(argc,argv);QTemporaryDir temporary;temporary.setAutoRemove(false);try{verify(argc==2&&temporary.isValid());const auto assets=std::filesystem::path(argv[1])/"assets/dictionary";auto direct=inkbound::dictionary::offlineDictionary(assets/"wordnet.ibd");auto chain=inkbound::dictionary::offlineDictionaryChain(assets,"They would walk along the river where water meets the bank.");verify(chain->isAvailable()&&chain->isOffline());for(auto word:{"reader","children","walking","books","would","ought"}){auto result=chain->lookup("en",word);verify(result&&!result->senses.empty()&&!result->sourceAttribution.empty());verify(result->sourceId=="princeton-wordnet-3.0"||result->sourceId=="gnu-gcide-0.54");verify(!result->senses.front().definition.empty()&&result->senses.front().definition.size()<=2048);}auto would=chain->lookup("en","would");verify(!direct->lookup("en","would")&&would&&would->sourceId=="gnu-gcide-0.54"&&would->senses.front().definition.find("auxiliary")!=std::string::npos);auto bank=chain->lookup("en","bank");verify(bank&&QString::fromStdString(bank->senses.front().definition).contains(QRegularExpression("water|river|land",QRegularExpression::CaseInsensitiveOption)));verify(!chain->lookup("en","zzunattestedlexeme987654321")&&!chain->lookup("fr","reader"));verify(!chain->lookup("en",std::string(513,'a'))&&!chain->lookup("en",std::string("\xff\xff",2)));auto cafe=chain->lookup("en","café");verify(cafe&&!cafe->senses.empty());
 auto root=std::filesystem::path(temporary.path().toStdString());std::filesystem::copy_file(assets/"gcide.ibd",root/"gcide.ibd");auto fallback=inkbound::dictionary::offlineDictionaryChain(root);verify(fallback->isAvailable()&&fallback->lookup("en","would"));underlay::atomicFile(root/"wordnet.ibd","corrupt dictionary");fallback=inkbound::dictionary::offlineDictionaryChain(root);verify(fallback->isAvailable()&&fallback->lookup("en","would"));std::filesystem::remove(root/"wordnet.ibd");std::filesystem::create_symlink(assets/"wordnet.ibd",root/"wordnet.ibd");fallback=inkbound::dictionary::offlineDictionaryChain(root);verify(fallback->isAvailable()&&fallback->lookup("en","would"));std::filesystem::remove(root/"gcide.ibd");fallback=inkbound::dictionary::offlineDictionaryChain(root);verify(!fallback->isAvailable()&&!fallback->lookup("en","reader"));verify(temporary.remove());std::printf("DICTIONARY_CHAIN_PASS checks=%u sources=WordNet_GCIDE context_ranked=true morphy_candidate_verified=true no_user_disambiguation=true no_network=true missing_corrupt_symlink_fallback=true physical=NOT_RUN\n",checks);return 0;}catch(const std::exception&e){std::fprintf(stderr,"DICTIONARY_CHAIN_FAIL %s fixture=%s\n",e.what(),temporary.path().toLocal8Bit().constData());return 1;}}
